import React, { useState, useRef } from "react";
import { 
  X, User, Truck, AlertCircle, BookOpen, 
  CheckCircle, Activity, MapPin
} from "lucide-react";
import ScheduleTab from "../tabs/ScheduleTab";
import ReportsTab from "../tabs/ReportsTab";
import TrainingTab from "../tabs/TrainingTab";

const WorkerDashboard = () => {
  const [activeTab, setActiveTab] = useState("schedule");
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [selectedReport, setSelectedReport] = useState(null);

  // Visibility States
  const [isAtTop, setIsAtTop] = useState(true);
  const [showFooter, setShowFooter] = useState(true);

  const scrollRef = useRef(null);

  const tabs = [
    { id: "schedule", label: "Tasks", icon: <Truck size={24} />, title: "Todays Schedule" },
    { id: "reports", label: "Issues", icon: <AlertCircle size={24} />, title: "Issues" },
    { id: "training", label: "Learn", icon: <BookOpen size={24} />, title: "Learn" },
  ];

  const handleOpenReport = (locationId) => {
    // Report logic remains untouched
  };

  const scrollToTab = (tabId) => {
    const index = tabs.findIndex(t => t.id === tabId);
    setActiveTab(tabId);
    setIsAtTop(true);
    setShowFooter(true);
    scrollRef.current.scrollTo({ left: index * window.innerWidth, behavior: "smooth" });
  };

  const handleHorizontalScroll = () => {
    if (scrollRef.current) {
      const index = Math.round(scrollRef.current.scrollLeft / window.innerWidth);
      if (tabs[index] && tabs[index].id !== activeTab) {
        setActiveTab(tabs[index].id);
        setIsAtTop(true);
        setShowFooter(true);
      }
    }
  };

  const handleVerticalScroll = (e) => {
    const { scrollTop, scrollHeight, clientHeight } = e.target;

    // 1. Profile Logic: Only show when strictly at the top
    setIsAtTop(scrollTop < 10);

    // 2. Footer Logic: Hide when scrolling down, show when scrolling up OR at edges
    // This mimics the Safari URL bar behavior
    const atBottom = scrollTop + clientHeight >= scrollHeight - 80;
    setShowFooter(atBottom || scrollTop < 10);
  };

  return (
    <div className="h-screen bg-[#FDFAD8] font-sans relative overflow-hidden">

      {/* --- 1. PROFILE TRIGGER (APPLE-STYLE FLOAT) --- */}
      <div className={`fixed top-10 right-8 z-[210] transition-all duration-500 ease-[cubic-bezier(0.4,0,0.2,1)] ${isAtTop ? "opacity-100 translate-y-0" : "opacity-0 -translate-y-10 pointer-events-none"}`}>
        <button 
          onClick={() => setIsProfileOpen(true)} 
          className="bg-[#47510B] p-2 pr-6 rounded-2xl flex items-center gap-3 border-2 border-white shadow-2xl text-[#CAD23C] active:scale-90 transition-all"
        >
          <div className="w-10 h-10 rounded-xl bg-[#CAD23C] flex items-center justify-center text-[#47510B] shadow-inner">
            <User size={22} strokeWidth={3} />
          </div>
          <span className="font-black text-[12px] uppercase tracking-widest font-mono">Profile</span>
        </button>
      </div>

      {/* --- 2. THE PROFILE LAYER (FULL RESTORATION) --- */}
      <div className={`absolute inset-0 z-[300] transition-all duration-1000 ease-[cubic-bezier(0.23,1,0.32,1)] flex items-center justify-center p-4 md:p-12 ${isProfileOpen ? "opacity-100 scale-100 translate-z-0" : "opacity-0 scale-125 translate-z-[-500px] pointer-events-none"}`}>
        <div className="w-full h-full bg-[#FDFAD8] rounded-[60px] shadow-2xl relative overflow-hidden flex flex-col border-[12px] border-white">
          <button onClick={() => setIsProfileOpen(false)} className="absolute top-6 right-6 w-12 h-12 bg-white rounded-full flex items-center justify-center text-[#47510B] hover:rotate-90 transition-transform shadow-xl z-50 border-2 border-[#47510B]/5">
            <X size={24} />
          </button>

          <div className="flex-1 overflow-y-auto no-scrollbar p-8 md:p-16">
            <div className="flex flex-col md:flex-row justify-between items-start gap-8 mb-12">
              <div>
                <h3 className="text-5xl font-black italic text-[#47510B] uppercase tracking-tighter leading-none mb-4">Marcus<br/><span className="text-[#CAD23C]">Sterling.</span></h3>
                <div className="flex gap-2">
                  <span className="px-3 py-1 bg-[#47510B] text-[#CAD23C] rounded-lg text-[9px] font-black uppercase tracking-widest">UNIT_7729</span>
                  <span className="px-3 py-1 border-2 border-[#47510B] text-[#47510B] rounded-lg text-[9px] font-black uppercase tracking-widest">SECTOR_04</span>
                </div>
              </div>
              <div className="flex gap-3">
                <div className="bg-[#CAD23C] px-6 py-4 rounded-[25px] border-2 border-[#47510B] text-center shadow-[4px_4px_0_0_#47510B]">
                  <p className="text-[8px] font-black opacity-60 uppercase text-[#47510B]">Badges</p>
                  <p className="text-xl font-black italic text-[#47510B]">12</p>
                </div>
                <div className="bg-[#AB1717] px-6 py-4 rounded-[25px] border-2 border-[#47510B] text-center text-white shadow-[4px_4px_0_0_#47510B]">
                  <p className="text-[8px] font-black opacity-60 uppercase text-[#FDFAD8]">Strikes</p>
                  <p className="text-xl font-black italic text-[#FDFAD8]">01</p>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-12">
              <div className="p-5 bg-white rounded-[30px] border-2 border-[#47510B]/10"><p className="text-[9px] font-black text-[#A1AED1] uppercase mb-1 tracking-widest font-mono">Registry_Email</p><p className="font-bold text-[#47510B] text-sm lowercase">m.sterling@trash2track.gov</p></div>
              <div className="p-5 bg-white rounded-[30px] border-2 border-[#47510B]/10"><p className="text-[9px] font-black text-[#A1AED1] uppercase mb-1 tracking-widest font-mono">Comm_Line</p><p className="font-bold text-[#47510B] text-sm">+44 7700 90001</p></div>
              <div className="p-5 bg-white rounded-[30px] border-2 border-[#47510B]/10"><p className="text-[9px] font-black text-[#A1AED1] uppercase mb-1 tracking-widest font-mono">License_Class</p><p className="font-bold text-[#47510B] text-sm uppercase">HGV / Heavy_Lift</p></div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
              <div>
                <h4 className="flex items-center gap-2 text-xl font-black italic text-[#47510B] uppercase tracking-tighter mb-4 px-2"><Truck size={18} /> Pickup_Archive</h4>
                <div className="space-y-2">
                  {[1, 2, 3].map((i) => (
                    <div key={i} className="p-4 rounded-[20px] border-2 border-[#47510B] bg-white shadow-[4px_4px_0_0_#CAD23C] flex items-center justify-between">
                      <div className="flex items-center gap-3"><CheckCircle size={14} className="text-[#47510B]" /><p className="text-[10px] font-black text-[#47510B] uppercase">Sector_0{i}_Node</p></div>
                      <span className="text-[8px] font-black bg-[#47510B] text-[#CAD23C] px-2 py-0.5 rounded uppercase">Verified</span>
                    </div>
                  ))}
                </div>
              </div>
              <div>
                <h4 className="flex items-center gap-2 text-xl font-black italic text-[#47510B] uppercase tracking-tighter mb-4 px-2"><Activity size={18} /> Resolution_Logs</h4>
                <div className="space-y-2">
                  {[1, 2, 3].map((i) => (
                    <div key={i} className="p-4 rounded-[20px] border-2 border-[#47510B] bg-white shadow-[4px_4px_0_0_#AB1717] flex items-center justify-between">
                      <div className="flex items-center gap-3"><AlertCircle size={14} className="text-[#AB1717]" /><p className="text-[10px] font-black text-[#47510B] uppercase">Issue_Fixed_0{i}</p></div>
                      <div className="w-2 h-2 rounded-full bg-[#CAD23C]" />
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* --- 3. MAIN CONTENT (UNCONVENTIONAL OVERLAP FIX) --- */}
      <div className={`h-full w-full transition-all duration-1000 ease-[cubic-bezier(0.23,1,0.32,1)] flex flex-col ${isProfileOpen ? "scale-90 blur-xl opacity-40 pointer-events-none" : "scale-100 opacity-100"}`}>

        <main ref={scrollRef} onScroll={handleHorizontalScroll} className="flex-1 flex h-full overflow-x-auto snap-x snap-mandatory no-scrollbar scroll-smooth">
          {tabs.map((tab) => (
            <section 
              key={tab.id} 
              onScroll={handleVerticalScroll} 
              className="min-w-full h-full snap-start flex flex-col items-center overflow-y-auto no-scrollbar relative"
            >
              {/* Content Wrapper */}
              <div className="w-full max-w-md flex flex-col pt-24 px-6">
                <h2 className="text-4xl font-[1000] italic text-[#47510B] uppercase tracking-tighter mb-10 text-left">
                  {tab.title}<span className="text-[#CAD23C]">.</span>
                </h2>

                <div className="flex flex-col items-center w-full pb-40"> {/* PUSHES CONTENT ABOVE FOOTER AREA */}
                  {tab.id === 'schedule' && <ScheduleTab onViewReport={handleOpenReport} />}
                  {tab.id === 'reports' && <ReportsTab onSelectReport={setSelectedReport} />}
                  {tab.id === 'training' && <TrainingTab />}
                </div>
              </div>
            </section>
          ))}
        </main>

        {/* --- 4. THE FOOTER (APPLE DOCK LOGIC) --- */}
        <footer className={`fixed bottom-10 left-1/2 -translate-x-1/2 z-[250] transition-all duration-500 ease-[cubic-bezier(0.23,1,0.32,1)] ${showFooter ? "translate-y-0 opacity-100" : "translate-y-32 opacity-0 pointer-events-none"}`}>
          <nav className="bg-[#47510B]/90 backdrop-blur-2xl border border-white/20 px-4 py-3 rounded-[40px] shadow-[0_25px_50px_-12px_rgba(0,0,0,0.4)] flex items-center gap-2">
            {tabs.map((tab) => (
              <button 
                key={tab.id} 
                onClick={() => scrollToTab(tab.id)} 
                className={`flex items-center gap-3 px-8 py-4 rounded-[30px] transition-all duration-500 ${activeTab === tab.id ? "bg-[#CAD23C] text-[#47510B] shadow-lg scale-110" : "text-white/40"}`}
              >
                <div className="transition-transform duration-500">{tab.icon}</div>
                {activeTab === tab.id && <span className="text-[11px] font-[1000] uppercase tracking-[0.2em]">{tab.label}</span>}
              </button>
            ))}
          </nav>
        </footer>
      </div>
    </div>
  );
};

export default WorkerDashboard;
